use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    let mut width = 0
    let mut ok = false
    let mut words: Vec<string> = []
    for line in text.lines() {
        if first {
            first = false
            let t = line.trim()
            match t.parse::<int>() {
                Ok(n) => {
                    if n > 0 {
                        width = n
                        ok = true
                    }
                }
                Err(_) => {}
            }
        } else {
            for w in line.split_whitespace() {
                words.push(w)
            }
        }
    }
    if !ok {
        println("error: bad width")
        std::process::exit(1)
    }
    let mut cur = ""
    let mut curlen: int = 0
    for w in words {
        let wl: int = w.chars().count() as int
        if curlen == 0 {
            cur = w
            curlen = wl
        } else if curlen + 1 + wl <= width {
            cur = "${cur} ${w}"
            curlen = curlen + 1 + wl
        } else {
            println(cur)
            cur = w
            curlen = wl
        }
    }
    if curlen > 0 {
        println(cur)
    }
}

